class _StartState extends State<RestoredStartScreen>{
 int step=0,photos=0;String gender='',orientation='',name='',age='',bio='';final looking=<String>{};final desires=<String>{};
 bool get ok=>step==0?gender.isNotEmpty:step==1?name.isNotEmpty&&int.tryParse(age)!=null&&orientation.isNotEmpty:step==2?looking.isNotEmpty:step==3?photos>=2:desires.isNotEmpty&&bio.trim().isNotEmpty;
