  if(step==1)return Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('A few extra details',style:TextStyle(fontSize:30,fontWeight:FontWeight.w900)),const SizedBox(height:20),TextField(onChanged:(v)=>name=v,decoration:const InputDecoration(labelText:'First name',border:OutlineInputBorder())),const SizedBox(height:14),TextField(onChanged:(v)=>age=v,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Age',border:OutlineInputBorder())),const SizedBox(height:18),const Text('Sexuality / orientation',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold)),Wrap(spacing:8,children:['Straight','Bi','Gay','Lesbian','Pansexual','Queer'].map((x)=>ChoiceChip(label:Text(x),selected:orientation==x,onSelected:(_)=>setState(()=>orientation=x))).toList())]);
  if(step==2)return _chips('What are you looking for?',lookingForOptions,looking,8);
  if(step==3)return Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Your photos',style:TextStyle(fontSize:30,fontWeight:FontWeight.w900)),const SizedBox(height:8),const Text('At least 2 · maximum 5'),const SizedBox(height:20),GridView.count(crossAxisCount:3,shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),crossAxisSpacing:10,mainAxisSpacing:10,children:List.generate(5,(i)=>InkWell(onTap:()async{final x=await ImagePicker().pickImage(source:ImageSource.gallery);if(x!=null&&photos<5)setState(()=>photos++);},child:Container(decoration:BoxDecoration(color:Colors.grey.shade200,borderRadius:BorderRadius.circular(16)),child:Icon(i<photos?Icons.check_circle:Icons.add_a_photo,color:i<photos?Colors.green:Colors.grey)))))]); 
  return Column(crossAxisAlignment:CrossAxisAlignment.start,children:[_chips('Desires',desireOptions,desires,8),const SizedBox(height:20),const Text('Bio',style:TextStyle(fontWeight:FontWeight.bold,fontSize:18)),const SizedBox(height:8),TextField(maxLines:5,onChanged:(v)=>bio=v,decoration:const InputDecoration(hintText:'Tell people about you / us...',border:OutlineInputBorder()))]);
 }
 Widget _choices(String title,List<String> xs,String selected,ValueChanged<String> f)=>Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:const TextStyle(fontSize:32,fontWeight:FontWeight.w900)),const SizedBox(height:8),const Text('Choose your profile type'),const SizedBox(height:22),...xs.map((x)=>Padding(padding:const EdgeInsets.only(bottom:12),child:SizedBox(width:double.infinity,height:62,child:OutlinedButton(onPressed:()=>f(x),style:OutlinedButton.styleFrom(side:BorderSide(color:selected==x?restoredPrimary:Colors.grey,width:selected==x?2:1),shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(17))),child:Row(children:[Icon(selected==x?Icons.radio_button_checked:Icons.radio_button_off,color:selected==x?restoredPrimary:Colors.grey),const SizedBox(width:12),Text(x)]))))]);
 Widget _chips(String title,List<String> xs,Set<String> selected,int max)=>Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:const TextStyle(fontSize:30,fontWeight:FontWeight.w900)),const SizedBox(height:7),Text('Pick up to '+max.toString()),const SizedBox(height:18),Wrap(spacing:8,runSpacing:8,children:xs.map((x)=>FilterChip(label:Text(x),selected:selected.contains(x),onSelected:(v)=>setState((){if(v&&selected.length<max)selected.add(x);if(!v)selected.remove(x);}))).toList())]);
}

