class _MapState extends State<RestoredMap>{LatLng center=const LatLng(28.4089,77.3178);@override void initState(){super.initState();_locate();}Future<void>_locate()async{try{if(await Geolocator.isLocationServiceEnabled()){var p=await Geolocator.checkPermission();if(p==LocationPermission.denied)p=await Geolocator.requestPermission();if(p==LocationPermission.always||p==LocationPermission.whileInUse){final x=await Geolocator.getCurrentPosition();center=LatLng(x.latitude,x.longitude);if(mounted)setState((){});}}}catch(_){}}@override Widget build(BuildContext c){final o=[const LatLng(.006,.004),const LatLng(-.004,.007),const LatLng(.008,-.006),const LatLng(-.007,-.004)];return FlutterMap(options:MapOptions(initialCenter:center,initialZoom:11.8),children:[TileLayer(urlTemplate:'https://tile.openstreetmap.org/{z}/{x}/{y}.png',userAgentPackageName:'com.aistudio.threetrio.jxhk'),MarkerLayer(markers:List.generate(profiles.length,(i)=>Marker(point:LatLng(center.latitude+o[i].latitude,center.longitude+o[i].longitude),width:100,height:90,child:GestureDetector(onTap:()=>showModalBottomSheet(context:c,builder:(_)=>_MapCard(p:profiles[i])),child:Column(children:[CircleAvatar(radius:27,backgroundImage:NetworkImage(profiles[i].photo)),Container(color:Colors.white,padding:const EdgeInsets.symmetric(horizontal:4,vertical:2),child:Text(profiles[i].name+' · '+(10+i*7).toString()+' km',style:const TextStyle(fontSize:9,fontWeight:FontWeight.bold)))])))))]);}}
